import{_ as e,o as a,c as i,ag as d}from"./chunks/framework.DyxC4IQh.js";const m=JSON.parse('{"title":"启用无障碍服务","description":"","frontmatter":{},"headers":[],"relativePath":"guide/accessibility.md","filePath":"guide/accessibility.md","lastUpdated":1792178988000}'),o={name:"guide/accessibility.md"};function c(r,t,l,s,n,h){return a(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="启用无障碍服务" tabindex="-1">启用无障碍服务 <a class="header-anchor" href="#启用无障碍服务" aria-label="Permalink to &quot;启用无障碍服务&quot;">​</a></h1><p>VimAct 的三项核心能力，全部落在 Android 的无障碍服务（AccessibilityService）上。这也是它能在零 root 的前提下工作的唯一原因。</p><h2 id="为什么必须是它" tabindex="-1">为什么必须是它 <a class="header-anchor" href="#为什么必须是它" aria-label="Permalink to &quot;为什么必须是它&quot;">​</a></h2><p>要在别的 App 里完成「查看 → 定位 → 点击」，需要三件事，而整个公开 API 里同时提供这三件事的只有无障碍服务：</p><table tabindex="0"><thead><tr><th>需要的能力</th><th>对应配置</th><th>没有它会怎样</th></tr></thead><tbody><tr><td>读到当前屏幕的控件树和坐标</td><td><code>canRetrieveWindowContent</code></td><td>不知道该把标签画在哪里</td></tr><tr><td>拦下按键事件，自己处理</td><td><code>canRequestFilterKeyEvents</code></td><td><code>F</code> 只会打字，永远进不了 hint 模式</td></tr><tr><td>派发一次点击</td><td><code>canPerformGestures</code></td><td>有些控件的 <code>ACTION_CLICK</code> 失败时无路可走</td></tr></tbody></table><p>覆盖层走的是 <code>TYPE_ACCESSIBILITY_OVERLAY</code>。这个类型由无障碍服务自身授权，所以不需要 <code>MediaProjection</code> 录屏权限，也不会看到那个「正在录屏」的系统提示。</p><h2 id="打开" tabindex="-1">打开 <a class="header-anchor" href="#打开" aria-label="Permalink to &quot;打开&quot;">​</a></h2><ol><li>系统设置 → 无障碍 →（不同 ROM 名称略有差异）已下载的应用 / 已安装的服务。</li><li>列表里选 VimAct。</li><li>打开开关，系统会弹出「允许此服务读取所有窗口内容」之类的授权确认，同意。</li></ol><p>从 VimAct 主页点「Open accessibility settings」会直接打开系统的无障碍设置页，省掉第 1 步的找路。列表还在，VimAct 还是要自己选中、开关还是要自己打开。</p><p>关掉开关，VimAct 立刻完全失效：不读屏幕、不贴标签、不碰按键。它没有任何后台常驻的意义。</p><h2 id="各家-rom-的额外坑" tabindex="-1">各家 ROM 的额外坑 <a class="header-anchor" href="#各家-rom-的额外坑" aria-label="Permalink to &quot;各家 ROM 的额外坑&quot;">​</a></h2><p>无障碍服务在国产 ROM 上属于容易被回收的进程，以下几种情况会导致「装了、开了、但按 <code>F</code> 没反应」：</p><ul><li>省电策略把应用冻结。需要在电池设置里给 VimAct 放行「无限制」或允许后台运行。</li><li>「清理加速」类功能一键杀掉了服务。重新打开开关即可，但要意识到它会反复发生。</li><li>部分机型要求「自启动」权限，否则系统重启后服务不会自动恢复。</li></ul><p>这类问题属于 OEM 兼容性，是 v0.1 明确列出的风险项。遇到时先按上面三条排查，再考虑<a href="/vimact-site/guide/faq.html">常见问题</a>里的其他原因。</p><h2 id="它能看到什么" tabindex="-1">它能看到什么 <a class="header-anchor" href="#它能看到什么" aria-label="Permalink to &quot;它能看到什么&quot;">​</a></h2><p>无障碍服务能读到当前窗口的控件树：节点类名、<code>viewId</code>、文本、<code>contentDescription</code>、边界坐标。VimAct 用这些内容做两件事——判定哪些节点可点击，以及把标签画在正确的位置。</p><p>它读不到屏幕像素（那需要录屏权限），也读不到其他应用的私有数据。密码输入框一类的内容本身就不会以明文出现在节点文本里。</p><p>这些读取全部发生在内存中，用完即丢。APK 不申请 <code>INTERNET</code> 权限，也就是说它没有把任何东西送出去的通道。这一点可以直接从安装时的权限清单核验。</p>',18)])])}const _=e(o,[["render",c]]);export{m as __pageData,_ as default};
